// Reference to generated workflow functions
var (
	// fabricDeployRegistrationMutex is a mutex for registering fabric.v1.FabricDeploy workflows
	fabricDeployRegistrationMutex sync.Mutex
	// CreateNamespace creates a new Kubernetes namespace for an organization
	CreateNamespaceFunction func(workflow.Context, *CreateNamespaceInput) (*CreateNamespaceOutput, error)
	// CreateServiceAccount creates a Kubernetes service account for Vault authentication
	CreateServiceAccountFunction func(workflow.Context, *CreateServiceAccountInput) (*CreateServiceAccountOutput, error)
	// CreateVaultRole creates a Vault Kubernetes auth role for the service account
	CreateVaultRoleFunction func(workflow.Context, *CreateVaultRoleInput) (*CreateVaultRoleOutput, error)
	// DeployCA deploys the Fabric CA pod to the Kubernetes cluster
	DeployCafunction func(workflow.Context, *DeployCaInput) (*DeployCaOutput, error)
	// DeployCouchDB deploys a CouchDB instance for peer state storage
	// Each peer gets its own CouchDB instance
	DeployCouchDbfunction func(workflow.Context, *DeployCouchDbInput) (*DeployCouchDbOutput, error)
	// DeployOrderer deploys an orderer node with certificates and CSI volume mounts
	// Calls ProvisionOrdererWorkflow to generate certs, then deploys the orderer pod
	DeployOrdererFunction func(workflow.Context, *DeployOrdererInput) (*DeployOrdererOutput, error)
	// DeployOrg is the master workflow that orchestrates complete organization deployment
	// Execution flow:
	// 1. CreateNamespace
	// 2. CreateServiceAccount
	// 3. CreateVaultRole
	// 4. DeployCA
	// 5. CreateAffiliations (activity - for CA identity organization)
	// 6. BootstrapAdmin (workflow - create initial admin identity)
	// 7. For each peer_id (sequential):
	//   - DeployCouchDB (for this peer)
	//   - DeployPeer (this peer)
	//
	// 8. For each orderer_id (sequential):
	//   - DeployOrderer (this orderer)
	DeployOrgFunction func(workflow.Context, *DeployOrgInput) (*DeployOrgOutput, error)
	// DeployPeer deploys a peer node with certificates and CSI volume mounts
	// Calls ProvisionPeerWorkflow to generate certs, then deploys the peer pod
	DeployPeerFunction func(workflow.Context, *DeployPeerInput) (*DeployPeerOutput, error)
)

// FabricDeployWorkflowFunctions describes a mockable dependency for inlining workflows within other workflows
type (
	// FabricDeployWorkflowFunctions describes a mockable dependency for inlining workflows within other workflows
	FabricDeployWorkflowFunctions interface {
		// CreateNamespace creates a new Kubernetes namespace for an organization
		CreateNamespace(workflow.Context, *CreateNamespaceInput) (*CreateNamespaceOutput, error)
		// CreateServiceAccount creates a Kubernetes service account for Vault authentication
		CreateServiceAccount(workflow.Context, *CreateServiceAccountInput) (*CreateServiceAccountOutput, error)
		// CreateVaultRole creates a Vault Kubernetes auth role for the service account
		CreateVaultRole(workflow.Context, *CreateVaultRoleInput) (*CreateVaultRoleOutput, error)
		// DeployCA deploys the Fabric CA pod to the Kubernetes cluster
		DeployCa(workflow.Context, *DeployCaInput) (*DeployCaOutput, error)
		// DeployCouchDB deploys a CouchDB instance for peer state storage
		// Each peer gets its own CouchDB instance
		DeployCouchDb(workflow.Context, *DeployCouchDbInput) (*DeployCouchDbOutput, error)
		// DeployOrderer deploys an orderer node with certificates and CSI volume mounts
		// Calls ProvisionOrdererWorkflow to generate certs, then deploys the orderer pod
		DeployOrderer(workflow.Context, *DeployOrdererInput) (*DeployOrdererOutput, error)
		// DeployOrg is the master workflow that orchestrates complete organization deployment
		// Execution flow:
		// 1. CreateNamespace
		// 2. CreateServiceAccount
		// 3. CreateVaultRole
		// 4. DeployCA
		// 5. CreateAffiliations (activity - for CA identity organization)
		// 6. BootstrapAdmin (workflow - create initial admin identity)
		// 7. For each peer_id (sequential):
		//   - DeployCouchDB (for this peer)
		//   - DeployPeer (this peer)
		//
		// 8. For each orderer_id (sequential):
		//   - DeployOrderer (this orderer)
		DeployOrg(workflow.Context, *DeployOrgInput) (*DeployOrgOutput, error)
		// DeployPeer deploys a peer node with certificates and CSI volume mounts
		// Calls ProvisionPeerWorkflow to generate certs, then deploys the peer pod
		DeployPeer(workflow.Context, *DeployPeerInput) (*DeployPeerOutput, error)
	}
	// fabricDeployWorkflowFunctions provides an internal FabricDeployWorkflowFunctions implementation
	fabricDeployWorkflowFunctions struct{}
)

